def _image_message_convert(message: Message) -> dict[str, Any]:
        payload=message.model_dump(mode="json")
        images = payload.pop("images", [])

        if images:
            payload["content"] = [
                {
                    "type": "text",
                    "text": str(payload.get("content") or ""),
                },
                *images,
            ]

        return payload

